"""Native-provider contract for forward attention."""

from __future__ import annotations

from dataclasses import dataclass, field
from functools import cached_property, lru_cache

from kestrel_kernels.flash_attn.cute.variant import (
    FlashAttnVariant,
    build_sm90_variants,
    build_sm100_variants,
)
from kestrel_kernels.native_coverage import (
    KernelDemand,
    NativeResolution,
    NativeTarget,
    ProviderResult,
    Rejection,
)


ATTENTION_FORWARD_OP_KIND = "attention.forward"
SM90_FORWARD_PROVIDER_NAME = "flash_attention_forward_sm90"
SM90_FORWARD_TARGET = NativeTarget("cuda", "sm90")
SM100_FORWARD_PROVIDER_NAME = "flash_attention_forward_sm100"
SM100_FORWARD_TARGET = NativeTarget("cuda", "sm100")
SM110_FORWARD_TARGET = NativeTarget("cuda", "sm110")


def attention_layout(
    *,
    paged_kv: bool,
    cu_seqlens_q: bool,
    cu_seqlens_k: bool,
) -> str:
    """Canonical logical layout for a forward attention demand."""

    q_layout = "thd" if cu_seqlens_q else "bshd"
    if paged_kv:
        kv_layout = "paged_bphd"
    else:
        kv_layout = "thd" if cu_seqlens_k else "bshd"
    return f"q_{q_layout}__kv_{kv_layout}"


@lru_cache(maxsize=512)
def forward_attention_demand(
    *,
    input_dtype,
    storage_dtype,
    q_heads: int,
    k_heads: int,
    v_heads: int,
    q_head_dim: int,
    k_head_dim: int,
    v_head_dim: int,
    paged_kv: bool,
    causal: bool,
    mask: str | None,
    window_size_left: int | None,
    window_size_right: int | None,
    cu_seqlens_q: bool,
    cu_seqlens_k: bool,
    seqused_q: bool,
    seqused_k: bool,
    aux_tensor_count: int,
    score_mod: bool,
    softcap: bool,
    learnable_sink: bool,
    return_lse: bool,
    split_kv: bool,
    requested_pack_gqa: bool | None,
    requested_value_splits: int | None = None,
    batch_size: int = 0,
    q_len: int = 0,
    kv_len: int = 0,
    num_sms: int = 0,
) -> KernelDemand:
    """Describe forward attention without selecting an implementation."""

    return KernelDemand(
        op_kind=ATTENTION_FORWARD_OP_KIND,
        input_dtype=input_dtype,
        storage_dtype=storage_dtype,
        layout=attention_layout(
            paged_kv=paged_kv,
            cu_seqlens_q=cu_seqlens_q,
            cu_seqlens_k=cu_seqlens_k,
        ),
        dimensions={
            "q_heads": q_heads,
            "k_heads": k_heads,
            "v_heads": v_heads,
            "q_head_dim": q_head_dim,
            "k_head_dim": k_head_dim,
            "v_head_dim": v_head_dim,
            "batch_size": batch_size,
            "q_len": q_len,
            "kv_len": kv_len,
            "num_sms": num_sms,
        },
        semantics={
            "aux_tensor_count": aux_tensor_count,
            "causal": causal,
            "cu_seqlens_k": cu_seqlens_k,
            "cu_seqlens_q": cu_seqlens_q,
            "learnable_sink": learnable_sink,
            "mask": mask,
            "paged_kv": paged_kv,
            "requested_pack_gqa": requested_pack_gqa,
            "requested_value_splits": requested_value_splits,
            "return_lse": return_lse,
            "score_mod": score_mod,
            "seqused_k": seqused_k,
            "seqused_q": seqused_q,
            "softcap": softcap,
            "split_kv": split_kv,
            "window_size_left": window_size_left,
            "window_size_right": window_size_right,
        },
    )


def _semantics(demand: KernelDemand) -> dict[str, object]:
    return dict(demand.semantics)


def _reject(
    demand: KernelDemand,
    target: NativeTarget,
    provider: str,
    code: str,
    reason: str,
    *,
    details=(),
) -> Rejection:
    return Rejection(
        provider=provider,
        target=target,
        demand=demand,
        code=code,
        reason=reason,
        details=details,
    )


@dataclass(frozen=True, eq=False)
class ForwardAttentionProvider:
    """Resolve semantic attention demands against one typed AOT inventory."""

    name: str
    targets: frozenset[NativeTarget]
    variants: tuple[FlashAttnVariant, ...] = field(repr=False)
    op_kinds: frozenset[str] = field(
        default=frozenset({ATTENTION_FORWARD_OP_KIND}),
        init=False,
    )

    @staticmethod
    def _variant_signature(variant: FlashAttnVariant) -> tuple[object, ...]:
        return (
            variant.dtype_name,
            variant.dtype_kv_name or variant.dtype_name,
            variant.head_dim,
            variant.causal,
            variant.mask_mod_name,
            variant.paged_kv_non_tma,
            variant.seqused_q,
            variant.dense_seqused_k,
            variant.cu_seqlens_q,
            variant.cu_seqlens_k,
            variant.qhead_per_kvhead,
            variant.local,
        )

    @cached_property
    def _variants_by_signature(
        self,
    ) -> dict[tuple[object, ...], tuple[FlashAttnVariant, ...]]:
        indexed: dict[tuple[object, ...], list[FlashAttnVariant]] = {}
        for variant in self.variants:
            indexed.setdefault(self._variant_signature(variant), []).append(variant)
        return {
            signature: tuple(sorted(variants, key=lambda item: item.value_splits))
            for signature, variants in indexed.items()
        }

    @cached_property
    def _variants_by_key(self) -> dict[str, FlashAttnVariant]:
        indexed = {variant.variant_key: variant for variant in self.variants}
        if len(indexed) != len(self.variants):
            raise RuntimeError(
                f"{self.name} inventory contains duplicate artifact keys"
            )
        return indexed

    @lru_cache(maxsize=512)
    def resolve(self, demand: KernelDemand, target: NativeTarget) -> ProviderResult:
        if demand.op_kind not in self.op_kinds:
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_operation",
                f"provider does not implement {demand.op_kind!r}",
            )
        if target not in self.targets:
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_target",
                "provider does not ship for the requested target",
            )
        if demand.input_dtype != "bf16":
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_dtype",
                "native forward attention requires BF16 queries",
                details={"input_dtype": demand.input_dtype},
            )
        if demand.storage_dtype not in ("bf16", "fp8_e4m3"):
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_storage_dtype",
                "native forward attention requires BF16 or FP8 E4M3 KV storage",
                details={"storage_dtype": demand.storage_dtype},
            )

        required_dimensions = (
            "batch_size",
            "q_len",
            "kv_len",
            "num_sms",
            "q_heads",
            "k_heads",
            "v_heads",
            "q_head_dim",
            "k_head_dim",
            "v_head_dim",
        )
        try:
            dimensions = {
                name: demand.dimension(name) for name in required_dimensions
            }
        except KeyError as exc:
            return _reject(
                demand,
                target,
                self.name,
                "missing_dimension",
                f"forward attention requires dimension {exc.args[0]!r}",
            )
        shape_dimensions = {
            name: dimensions[name]
            for name in (
                "q_heads",
                "k_heads",
                "v_heads",
                "q_head_dim",
                "k_head_dim",
                "v_head_dim",
            )
        }
        if any(value < 1 for value in shape_dimensions.values()):
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_shape",
                "forward attention dimensions must be positive",
                details=shape_dimensions,
            )
        if dimensions["k_heads"] != dimensions["v_heads"]:
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_shape",
                "K and V head counts must match",
                details=dimensions,
            )
        if dimensions["q_heads"] % dimensions["k_heads"]:
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_shape",
                "Q heads must be divisible by KV heads",
                details=dimensions,
            )
        if not (
            dimensions["q_head_dim"]
            == dimensions["k_head_dim"]
            == dimensions["v_head_dim"]
        ):
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_shape",
                "shipped forward variants require equal Q, K, and V head dimensions",
                details=dimensions,
            )

        semantics = _semantics(demand)
        required_semantics = (
            "aux_tensor_count",
            "causal",
            "cu_seqlens_k",
            "cu_seqlens_q",
            "learnable_sink",
            "mask",
            "paged_kv",
            "requested_pack_gqa",
            "requested_value_splits",
            "return_lse",
            "score_mod",
            "seqused_k",
            "seqused_q",
            "softcap",
            "split_kv",
            "window_size_left",
            "window_size_right",
        )
        missing = tuple(name for name in required_semantics if name not in semantics)
        if missing:
            return _reject(
                demand,
                target,
                self.name,
                "missing_semantics",
                "forward attention demand is incomplete",
                details={"missing": missing},
            )

        unsupported_features = tuple(
            name
            for name in (
                "learnable_sink",
                "return_lse",
                "score_mod",
                "softcap",
                "split_kv",
            )
            if semantics[name]
        )
        if unsupported_features:
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_semantics",
                "shipped forward variants do not implement requested semantics",
                details={"features": unsupported_features},
            )

        paged_kv = bool(semantics["paged_kv"])
        cu_seqlens_q = bool(semantics["cu_seqlens_q"])
        cu_seqlens_k = bool(semantics["cu_seqlens_k"])
        seqused_q = bool(semantics["seqused_q"])
        seqused_k = bool(semantics["seqused_k"])
        expected_layout = attention_layout(
            paged_kv=paged_kv,
            cu_seqlens_q=cu_seqlens_q,
            cu_seqlens_k=cu_seqlens_k,
        )
        if demand.layout != expected_layout:
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_layout",
                "attention layout disagrees with its paged/varlen semantics",
                details={"expected": expected_layout, "actual": demand.layout},
            )
        if paged_kv and cu_seqlens_k:
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_layout",
                "paged KV cannot also use packed K sequence offsets",
            )
        if cu_seqlens_q and seqused_q:
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_layout",
                "packed Q offsets and per-row used-Q lengths are mutually exclusive",
            )
        if paged_kv and not seqused_k:
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_layout",
                "shipped paged forward variants require used-K lengths",
            )

        window_left = semantics["window_size_left"]
        window_right = semantics["window_size_right"]
        if (window_left is None) != (window_right is None):
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_window",
                "local attention requires both runtime window bounds",
            )
        local = window_left is not None
        if local and (
            isinstance(window_left, bool)
            or isinstance(window_right, bool)
            or not isinstance(window_left, int)
            or not isinstance(window_right, int)
            or window_left < 0
            or window_right < 0
        ):
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_window",
                "runtime window bounds must be non-negative integers",
            )

        mask = semantics["mask"]
        aux_tensor_count = semantics["aux_tensor_count"]
        if isinstance(aux_tensor_count, bool) or not isinstance(aux_tensor_count, int):
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_auxiliary_inputs",
                "auxiliary tensor count must be an integer",
            )
        expected_aux_count = 1 if mask in {
            "block_bidirectional",
            "windowed_blockdiag",
        } else 0
        if aux_tensor_count != expected_aux_count:
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_auxiliary_inputs",
                "mask and auxiliary tensor ABI do not match",
                details={
                    "actual_count": aux_tensor_count,
                    "expected_count": expected_aux_count,
                    "mask": mask,
                },
            )

        qhead_per_kvhead = dimensions["q_heads"] // dimensions["k_heads"]
        head_dim = dimensions["q_head_dim"]
        signature = (
            demand.input_dtype,
            demand.storage_dtype,
            head_dim,
            bool(semantics["causal"]),
            mask,
            paged_kv,
            seqused_q,
            seqused_k and not paged_kv,
            cu_seqlens_q,
            cu_seqlens_k,
            qhead_per_kvhead,
            local,
        )
        variants = self._variants_by_signature.get(signature, ())
        requested_value_splits = semantics["requested_value_splits"]
        if requested_value_splits is not None:
            if (
                isinstance(requested_value_splits, bool)
                or not isinstance(requested_value_splits, int)
                or requested_value_splits < 1
            ):
                return _reject(
                    demand,
                    target,
                    self.name,
                    "unsupported_partition",
                    "requested value partition count must be a positive integer",
                    details={"requested_value_splits": requested_value_splits},
                )
            variants = tuple(
                variant
                for variant in variants
                if variant.value_splits == requested_value_splits
            )
        if not variants:
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_variant",
                "no shipped forward attention variant matches this demand",
                details={
                    "head_dim": head_dim,
                    "mask": mask,
                    "qhead_per_kvhead": qhead_per_kvhead,
                    "requested_value_splits": requested_value_splits,
                },
            )
        if len(variants) > 1:
            return _reject(
                demand,
                target,
                self.name,
                "selection_required",
                "multiple physical value partitions match this semantic demand",
                details={
                    "candidate_value_splits": tuple(
                        variant.value_splits for variant in variants
                    ),
                    "kv_len": dimensions["kv_len"],
                    "num_sms": dimensions["num_sms"],
                    "q_len": dimensions["q_len"],
                },
            )
        variant = variants[0]
        compiled_pack_gqa = variant.uses_packed_gqa
        requested_pack_gqa = semantics["requested_pack_gqa"]
        if requested_pack_gqa is not None and not isinstance(
            requested_pack_gqa, bool
        ):
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_layout",
                "requested packed-GQA layout must be true, false, or omitted",
                details={"requested_pack_gqa": requested_pack_gqa},
            )
        # ``None`` leaves layout selection entirely to the provider. ``True`` is
        # the historical "pack when legal" preference, so an indivisible group
        # may still resolve to the ordinary layout. Only explicit ``False`` is a
        # hard constraint because callers use it when their indexing ABI cannot
        # tolerate folded query coordinates.
        if requested_pack_gqa is False and compiled_pack_gqa:
            return _reject(
                demand,
                target,
                self.name,
                "unsupported_layout",
                "the shipped variant requires packed GQA but the caller forbids it",
                details={
                    "compiled_pack_gqa": compiled_pack_gqa,
                    "requested_pack_gqa": requested_pack_gqa,
                    "variant_key": variant.variant_key,
                },
            )

        batch_size = dimensions["batch_size"]
        q_len = dimensions["q_len"]
        num_sms = dimensions["num_sms"]
        if batch_size and q_len:
            if compiled_pack_gqa:
                q_tiles = (
                    q_len * qhead_per_kvhead + variant.tile_m - 1
                ) // variant.tile_m
                base_tasks = batch_size * dimensions["k_heads"] * q_tiles
            else:
                q_tiles = (q_len + variant.tile_m - 1) // variant.tile_m
                base_tasks = batch_size * dimensions["q_heads"] * q_tiles
            physical_tasks = base_tasks * variant.value_splits
            task_waves = (
                (physical_tasks + num_sms - 1) // num_sms if num_sms else 0
            )
        else:
            base_tasks = physical_tasks = task_waves = 0

        return NativeResolution(
            provider=self.name,
            implementation=variant.variant_key,
            target=target,
            demand=demand,
            constraints={
                "local_window_abi": variant.local,
                "num_stages": variant.num_stages,
                "pack_gqa": compiled_pack_gqa,
                "runtime_scalars": (
                    ("window_size_left", "window_size_right")
                    if variant.local
                    else ()
                ),
                "tile_m": variant.tile_m,
                "tile_n": variant.tile_n,
                "value_splits": variant.value_splits,
                "base_tasks": base_tasks,
                "physical_tasks": physical_tasks,
                "task_waves": task_waves,
            },
        )

    def variant_for(self, resolution: NativeResolution) -> FlashAttnVariant:
        if resolution.provider != self.name:
            raise ValueError(
                f"resolution belongs to provider {resolution.provider!r}, not {self.name!r}"
            )
        try:
            return self._variants_by_key[resolution.implementation]
        except KeyError as exc:
            raise ValueError(
                "resolution names unknown forward attention variant "
                f"{resolution.implementation!r}"
            ) from exc


SM90_FORWARD_PROVIDER = ForwardAttentionProvider(
    name=SM90_FORWARD_PROVIDER_NAME,
    targets=frozenset({SM90_FORWARD_TARGET}),
    variants=tuple(
        variant
        for variant in build_sm90_variants()
        if variant.kind == "forward_sm90"
    ),
)
SM100_FORWARD_PROVIDER = ForwardAttentionProvider(
    name=SM100_FORWARD_PROVIDER_NAME,
    targets=frozenset({SM100_FORWARD_TARGET, SM110_FORWARD_TARGET}),
    variants=tuple(
        variant
        for variant in build_sm100_variants()
        if variant.kind == "forward_sm100"
    ),
)
_FORWARD_PROVIDERS_BY_TARGET = {
    target: provider
    for provider in (SM90_FORWARD_PROVIDER, SM100_FORWARD_PROVIDER)
    for target in provider.targets
}


@dataclass(frozen=True)
class ForwardAttentionExecutionPlan:
    """Provider-certified data needed by the runtime launch boundary."""

    resolution: NativeResolution
    variant: FlashAttnVariant
    pack_gqa: bool


@lru_cache(maxsize=512)
def resolve_forward_attention_execution_plan(
    *,
    target: NativeTarget,
    input_dtype,
    storage_dtype,
    q_heads: int,
    k_heads: int,
    v_heads: int,
    q_head_dim: int,
    k_head_dim: int,
    v_head_dim: int,
    paged_kv: bool,
    causal: bool,
    mask: str | None,
    window_size_left: int | None,
    window_size_right: int | None,
    cu_seqlens_q: bool,
    cu_seqlens_k: bool,
    seqused_q: bool,
    seqused_k: bool,
    aux_tensor_count: int,
    score_mod: bool,
    softcap: bool,
    learnable_sink: bool,
    return_lse: bool,
    split_kv: bool,
    requested_pack_gqa: bool | None,
    requested_value_splits: int | None = None,
    batch_size: int = 0,
    q_len: int = 0,
    kv_len: int = 0,
    num_sms: int = 0,
) -> ForwardAttentionExecutionPlan | Rejection:
    """Bind structured provider resolution once per primitive runtime signature.

    Re-resolving the same structured demand between launches left identical
    H100 cubins at 41.9-42.2 us versus 40.0-40.1 us on the prior runtime;
    caching this launch plan restored 39.0-39.6 us. Compiler and diagnostic
    callers continue to use the full ``KernelDemand`` provider contract.
    """

    demand = forward_attention_demand(
        input_dtype=input_dtype,
        storage_dtype=storage_dtype,
        q_heads=q_heads,
        k_heads=k_heads,
        v_heads=v_heads,
        q_head_dim=q_head_dim,
        k_head_dim=k_head_dim,
        v_head_dim=v_head_dim,
        paged_kv=paged_kv,
        causal=causal,
        mask=mask,
        window_size_left=window_size_left,
        window_size_right=window_size_right,
        cu_seqlens_q=cu_seqlens_q,
        cu_seqlens_k=cu_seqlens_k,
        seqused_q=seqused_q,
        seqused_k=seqused_k,
        aux_tensor_count=aux_tensor_count,
        score_mod=score_mod,
        softcap=softcap,
        learnable_sink=learnable_sink,
        return_lse=return_lse,
        split_kv=split_kv,
        requested_pack_gqa=requested_pack_gqa,
        requested_value_splits=requested_value_splits,
        batch_size=batch_size,
        q_len=q_len,
        kv_len=kv_len,
        num_sms=num_sms,
    )
    provider = _FORWARD_PROVIDERS_BY_TARGET.get(target)
    if provider is None:
        return Rejection(
            provider="flash_attention_forward",
            target=target,
            demand=demand,
            code="unsupported_target",
            reason="no forward attention provider ships for the requested target",
        )
    resolution = provider.resolve(demand, target)
    if isinstance(resolution, Rejection):
        return resolution
    constraints = dict(resolution.constraints)
    return ForwardAttentionExecutionPlan(
        resolution=resolution,
        variant=provider.variant_for(resolution),
        pack_gqa=bool(constraints["pack_gqa"]),
    )


__all__ = [
    "ATTENTION_FORWARD_OP_KIND",
    "ForwardAttentionProvider",
    "ForwardAttentionExecutionPlan",
    "SM90_FORWARD_PROVIDER",
    "SM90_FORWARD_TARGET",
    "SM100_FORWARD_PROVIDER",
    "SM100_FORWARD_TARGET",
    "SM110_FORWARD_TARGET",
    "attention_layout",
    "forward_attention_demand",
    "resolve_forward_attention_execution_plan",
]
